export const featureKey=value=>String(value??'').normalize('NFD').replace(/\p{Diacritic}/gu,'').toLowerCase().replace(/\s+/g,' ').trim();
export function normalizeFeatures(value=[]){
 if(!Array.isArray(value)||value.length>250)throw Object.assign(Error('Selecione até 250 opcionais válidos.'),{status:400});
 const seen=new Set();return value.map(item=>{
  if(typeof item!=='string')throw Object.assign(Error('Opcional inválido.'),{status:400});
  const label=item.normalize('NFC').replace(/\s+/g,' ').trim();
  if(!label||label.length>100||/[<>\x00-\x1f]/.test(label))throw Object.assign(Error('Use nomes de opcionais com 1 a 100 caracteres, sem HTML.'),{status:400});
  return label;
 }).filter(label=>{const key=featureKey(label);if(seen.has(key))return false;seen.add(key);return true});
}
export function featureCatalog(custom=[]){
 const known=new Set(featureGroups.flatMap(group=>group.items.map(featureKey)));
 return [...featureGroups,{name:'Opcionais extras da loja',items:custom.map(item=>normalizeFeatures([item])[0]).filter(item=>!known.has(featureKey(item))).sort((a,b)=>a.localeCompare(b,'pt-BR'))}];
}
